    <td background="images/bg.gif"><font class=""><a href="modules.php?name=News&new_topic=5">Movies</a></font><br><font class="testo_notizia" color="#000000"><b>[<a href="modules.php?name=&amp;file=categories&amp;op=newindex&amp;catid=2"><font class="esclusiva">EXCLUSIVE</font></a>] Revolver premiere - Exclusive Photographs.</b></font></td>
